window.docContents[172].resolve({"/rules/RG1002/#RG1002-example":{"contents":"\n\nThe correction fills the same reflexivity proof with rfl. The checked violation records Lean's original sorry warning as well; the corrected file passes the ordinary warning-rejecting gate.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1002: Proof holes are forbidden","header":"Checked example","id":"/rules/RG1002/#RG1002-example"},"/rules/RG2001/#RG2001-example":{"contents":"\n\nThe correction removes the unavailable Lake dependency from the configuration; the requested reflexivity source is unchanged.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2001: The declared Lean environment must be available","header":"Checked example","id":"/rules/RG2001/#RG2001-example"}});